Dataspatium.assets.register("presets/ids/SE-Dataspatium_Klimatdeklaration.ids","text","<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!-- SPDX-License-Identifier: LicenseRef-PolyForm-Strict-1.0.0 -->\n<!-- Dataspatium's own requirements for a preliminary climate declaration, written from open rules: the common property sets and\n     base quantities of IFC (IfcOpenShell's templates of the schema), IfcMaterial.Category, and Boverket's four categories (load\n     bearing parts, the climate envelope, interior walls), which the app reads from the IFC class, LoadBearing and IsExternal\n     (Analysera, Mängder, Klimatdeklaration). No classification system is needed. -->\n<ids xmlns=\"http://standards.buildingsmart.org/IDS\" xmlns:xs=\"http://www.w3.org/2001/XMLSchema\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xsi:schemaLocation=\"http://standards.buildingsmart.org/IDS http://standards.buildingsmart.org/IDS/1.0/ids.xsd\">\n  <info>\n    <title>SE-Dataspatium_Klimatdeklaration</title>\n    <copyright>Dataspatium</copyright>\n    <version>1.0</version>\n    <description>Det en preliminär klimatdeklaration behöver ur modellen: om väggar, bjälklag, tak, pelare och balkar är bärande, om väggar, dörrar och fönster sitter i klimatskärmen, material med kategori på byggdelarna, och basmängder.</description>\n    <date>2026-11-12</date>\n    <purpose>Klimatdeklaration</purpose>\n  </info>\n  <specifications>\n    <specification name=\"Väggen är bärande eller inte\" ifcVersion=\"IFC2X3 IFC4 IFC4X3_ADD2\" identifier=\"K01\" description=\"Pset_WallCommon.LoadBearing är satt, på väggen eller dess typ.\" instructions=\"Ange om väggen är bärande.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCWALL</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <property dataType=\"IFCBOOLEAN\" cardinality=\"required\"><propertySet><simpleValue>Pset_WallCommon</simpleValue></propertySet><baseName><simpleValue>LoadBearing</simpleValue></baseName></property>\n      </requirements>\n    </specification>\n    <specification name=\"Bjälklaget eller takskivan är bärande eller inte\" ifcVersion=\"IFC2X3 IFC4 IFC4X3_ADD2\" identifier=\"K02\" description=\"Pset_SlabCommon.LoadBearing är satt, även på takets skivor (IfcSlab ROOF).\" instructions=\"Ange om bjälklaget eller takskivan är bärande.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCSLAB</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <property dataType=\"IFCBOOLEAN\" cardinality=\"required\"><propertySet><simpleValue>Pset_SlabCommon</simpleValue></propertySet><baseName><simpleValue>LoadBearing</simpleValue></baseName></property>\n      </requirements>\n    </specification>\n    <specification name=\"Taket är bärande eller inte\" ifcVersion=\"IFC4X3_ADD2\" identifier=\"K03\" description=\"Pset_RoofCommon.LoadBearing är satt (IFC 4.3; i IFC4 bär takets skivor uppgiften).\" instructions=\"Ange om taket är bärande.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCROOF</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <property dataType=\"IFCBOOLEAN\" cardinality=\"required\"><propertySet><simpleValue>Pset_RoofCommon</simpleValue></propertySet><baseName><simpleValue>LoadBearing</simpleValue></baseName></property>\n      </requirements>\n    </specification>\n    <specification name=\"Pelaren är bärande eller inte\" ifcVersion=\"IFC2X3 IFC4 IFC4X3_ADD2\" identifier=\"K04\" description=\"Pset_ColumnCommon.LoadBearing är satt.\" instructions=\"Ange om pelaren är bärande.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCCOLUMN</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <property dataType=\"IFCBOOLEAN\" cardinality=\"required\"><propertySet><simpleValue>Pset_ColumnCommon</simpleValue></propertySet><baseName><simpleValue>LoadBearing</simpleValue></baseName></property>\n      </requirements>\n    </specification>\n    <specification name=\"Balken är bärande eller inte\" ifcVersion=\"IFC2X3 IFC4 IFC4X3_ADD2\" identifier=\"K05\" description=\"Pset_BeamCommon.LoadBearing är satt.\" instructions=\"Ange om balken är bärande.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCBEAM</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <property dataType=\"IFCBOOLEAN\" cardinality=\"required\"><propertySet><simpleValue>Pset_BeamCommon</simpleValue></propertySet><baseName><simpleValue>LoadBearing</simpleValue></baseName></property>\n      </requirements>\n    </specification>\n    <specification name=\"Väggen sitter i klimatskärmen eller inte\" ifcVersion=\"IFC2X3 IFC4 IFC4X3_ADD2\" identifier=\"K06\" description=\"Pset_WallCommon.IsExternal är satt.\" instructions=\"Ange om väggen är en yttervägg.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCWALL</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <property dataType=\"IFCBOOLEAN\" cardinality=\"required\"><propertySet><simpleValue>Pset_WallCommon</simpleValue></propertySet><baseName><simpleValue>IsExternal</simpleValue></baseName></property>\n      </requirements>\n    </specification>\n    <specification name=\"Dörren sitter i klimatskärmen eller inte\" ifcVersion=\"IFC2X3 IFC4 IFC4X3_ADD2\" identifier=\"K07\" description=\"Pset_DoorCommon.IsExternal är satt.\" instructions=\"Ange om dörren är en ytterdörr.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCDOOR</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <property dataType=\"IFCBOOLEAN\" cardinality=\"required\"><propertySet><simpleValue>Pset_DoorCommon</simpleValue></propertySet><baseName><simpleValue>IsExternal</simpleValue></baseName></property>\n      </requirements>\n    </specification>\n    <specification name=\"Fönstret sitter i klimatskärmen eller inte\" ifcVersion=\"IFC2X3 IFC4 IFC4X3_ADD2\" identifier=\"K08\" description=\"Pset_WindowCommon.IsExternal är satt.\" instructions=\"Ange om fönstret sitter i en yttervägg eller ett tak.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCWINDOW</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <property dataType=\"IFCBOOLEAN\" cardinality=\"required\"><propertySet><simpleValue>Pset_WindowCommon</simpleValue></propertySet><baseName><simpleValue>IsExternal</simpleValue></baseName></property>\n      </requirements>\n    </specification>\n    <specification name=\"Byggdelen har material\" ifcVersion=\"IFC2X3 IFC4 IFC4X3_ADD2\" identifier=\"K09\" description=\"Väggar, bjälklag, pelare och balkar har ett material, gärna som skikt på typen.\" instructions=\"Ge byggdelen dess material, helst som materialskikt på typen.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><xs:restriction base=\"xs:string\"><xs:enumeration value=\"IFCWALL\"/><xs:enumeration value=\"IFCSLAB\"/><xs:enumeration value=\"IFCCOLUMN\"/><xs:enumeration value=\"IFCBEAM\"/></xs:restriction></name></entity>\n      </applicability>\n      <requirements>\n        <material cardinality=\"required\"/>\n      </requirements>\n    </specification>\n    <specification name=\"Materialet har en kategori\" ifcVersion=\"IFC4 IFC4X3_ADD2\" identifier=\"K10\" description=\"IfcMaterial.Category är satt, till exempel concrete, steel, wood, brick eller gypsum.\" instructions=\"Ange materialets kategori.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCMATERIAL</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <attribute cardinality=\"required\"><name><simpleValue>Category</simpleValue></name></attribute>\n      </requirements>\n    </specification>\n    <specification name=\"Väggen har basmängder\" ifcVersion=\"IFC4 IFC4X3_ADD2\" identifier=\"K11\" description=\"Qto_WallBaseQuantities med GrossSideArea och GrossVolume.\" instructions=\"Räkna väggens basmängder.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCWALL</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <property dataType=\"IFCAREAMEASURE\" cardinality=\"required\"><propertySet><simpleValue>Qto_WallBaseQuantities</simpleValue></propertySet><baseName><simpleValue>GrossSideArea</simpleValue></baseName></property>\n        <property dataType=\"IFCVOLUMEMEASURE\" cardinality=\"required\"><propertySet><simpleValue>Qto_WallBaseQuantities</simpleValue></propertySet><baseName><simpleValue>GrossVolume</simpleValue></baseName></property>\n      </requirements>\n    </specification>\n    <specification name=\"Bjälklaget har basmängder\" ifcVersion=\"IFC4 IFC4X3_ADD2\" identifier=\"K12\" description=\"Qto_SlabBaseQuantities med GrossArea och GrossVolume.\" instructions=\"Räkna bjälklagets basmängder.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCSLAB</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <property dataType=\"IFCAREAMEASURE\" cardinality=\"required\"><propertySet><simpleValue>Qto_SlabBaseQuantities</simpleValue></propertySet><baseName><simpleValue>GrossArea</simpleValue></baseName></property>\n        <property dataType=\"IFCVOLUMEMEASURE\" cardinality=\"required\"><propertySet><simpleValue>Qto_SlabBaseQuantities</simpleValue></propertySet><baseName><simpleValue>GrossVolume</simpleValue></baseName></property>\n      </requirements>\n    </specification>\n    <specification name=\"Taket har basmängder\" ifcVersion=\"IFC4 IFC4X3_ADD2\" identifier=\"K13\" description=\"Qto_RoofBaseQuantities med GrossArea.\" instructions=\"Räkna takets basmängder.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCROOF</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <property dataType=\"IFCAREAMEASURE\" cardinality=\"required\"><propertySet><simpleValue>Qto_RoofBaseQuantities</simpleValue></propertySet><baseName><simpleValue>GrossArea</simpleValue></baseName></property>\n      </requirements>\n    </specification>\n    <specification name=\"Pelaren har basmängder\" ifcVersion=\"IFC4 IFC4X3_ADD2\" identifier=\"K14\" description=\"Qto_ColumnBaseQuantities med GrossVolume.\" instructions=\"Räkna pelarens basmängder.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCCOLUMN</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <property dataType=\"IFCVOLUMEMEASURE\" cardinality=\"required\"><propertySet><simpleValue>Qto_ColumnBaseQuantities</simpleValue></propertySet><baseName><simpleValue>GrossVolume</simpleValue></baseName></property>\n      </requirements>\n    </specification>\n    <specification name=\"Balken har basmängder\" ifcVersion=\"IFC4 IFC4X3_ADD2\" identifier=\"K15\" description=\"Qto_BeamBaseQuantities med GrossVolume.\" instructions=\"Räkna balkens basmängder.\">\n      <applicability minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <entity><name><simpleValue>IFCBEAM</simpleValue></name></entity>\n      </applicability>\n      <requirements>\n        <property dataType=\"IFCVOLUMEMEASURE\" cardinality=\"required\"><propertySet><simpleValue>Qto_BeamBaseQuantities</simpleValue></propertySet><baseName><simpleValue>GrossVolume</simpleValue></baseName></property>\n      </requirements>\n    </specification>\n  </specifications>\n</ids>\n");
